try {
  var input = $input.first().json;
  var msg = (input.body && input.body.message) ? input.body.message : input;
  var raw = '';
  if (msg.call && msg.call.customer) {
    raw = msg.call.customer.number || msg.call.customer.phoneNumber || '';
  }
  raw = raw.replace(/\s/g, '');
  if (raw && raw.charAt(0) !== '+') { raw = '+' + raw; }
  return [{ json: { phone: raw } }];
} catch(e) {
  return [{ json: { phone: '', errorMsg: 'Extract Caller Phone failed: ' + e.message } }];
}

try {
  // B9: the Sheets node's built-in lookup is an EXACT string match on Phone. One historically
  // coerced number (missing '+', stray space) and a known customer is greeted as a stranger at
  // the start of an inbound call. Read the tab and match on digits instead.
  var wanted = String($('Extract Caller Phone').first().json.phone || '').replace(/[^0-9]/g, '');
  var rows = $input.all();
  var row = null;
  if (wanted) {
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i].json || {};
      var d = String(r['Phone'] || '').replace(/[^0-9]/g, '');
      if (!d) { continue; }
      // compare the last 9 digits so a missing or differing country code still matches
      var a = d.slice(-9);
      var b = wanted.slice(-9);
      if (d === wanted || (a.length === 9 && a === b)) { row = r; break; }
    }
  }
  var hasRecord = !!(row && row['Phone']);
  return [{
    json: {
      variables: {
        callerName:          hasRecord ? (row['Name'] || '')                 : '',
        serviceInterest:     hasRecord ? (row['Service Interest'] || '')     : '',
        isExistingLead:      hasRecord ? 'true'                              : 'false',
        callCount:           hasRecord ? String(row['Call Count'] || '0')    : '0',
        lastOutcome:         hasRecord ? (row['Last Outcome'] || '')         : '',
        upcomingAppointment: hasRecord ? (row['Upcoming Appointment'] || '') : '',
        callerStatus:        hasRecord ? (row['Status'] || '')               : '',
        lastChannel:         hasRecord ? (row['Last Channel'] || '')         : ''
      },
      matchedOn: hasRecord ? 'digits' : 'none',
      rowsScanned: rows.length
    }
  }];
} catch(e) {
  return [{ json: { variables: {}, errorMsg: 'Build Variables Response failed: ' + e.message } }];
}

